//! Standard Webhooks vectors generated by the real TS signer.

use pg_crypto::webhooks::{
    build_standard_webhook_headers, sign_standard_webhook, verify_standard_webhook_at,
};
use serde::Deserialize;
use std::collections::BTreeMap;

const WEBHOOKS: &str = include_str!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../tests/golden-vectors/webhooks.json"
));

#[derive(Deserialize)]
struct File {
    #[serde(rename = "signingSecret")]
    signing_secret: String,
    #[serde(rename = "rotationSecret")]
    rotation_secret: String,
    cases: Vec<Case>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Case {
    id: String,
    kind: String,
    webhook_id: String,
    timestamp_seconds: i64,
    body: String,
    #[serde(default)]
    secret: String,
    #[serde(default)]
    signature: String,
    #[serde(default)]
    secrets: Vec<String>,
    #[serde(default)]
    headers: BTreeMap<String, String>,
}

#[test]
fn signatures_match_typescript() {
    let file: File = serde_json::from_str(WEBHOOKS).expect("webhook vectors");
    let mut signs = 0;
    for case in file.cases.iter().filter(|case| case.kind == "sign") {
        signs += 1;
        let signature = sign_standard_webhook(
            &case.webhook_id,
            case.timestamp_seconds,
            &case.body,
            &case.secret,
        )
        .expect("sign");
        assert_eq!(signature, case.signature, "{}", case.id);
        assert!(signature.starts_with("v1,"));
        assert!(verify_standard_webhook_at(
            Some(&case.webhook_id),
            Some(&case.timestamp_seconds.to_string()),
            Some(&case.signature),
            &case.body,
            std::slice::from_ref(&case.secret),
            300,
            case.timestamp_seconds
        ));
        assert!(!verify_standard_webhook_at(
            Some(&case.webhook_id),
            Some(&case.timestamp_seconds.to_string()),
            Some(&case.signature),
            &format!("{} ", case.body),
            std::slice::from_ref(&case.secret),
            300,
            case.timestamp_seconds
        ));
        assert!(!verify_standard_webhook_at(
            Some(&case.webhook_id),
            Some(&case.timestamp_seconds.to_string()),
            Some(&case.signature),
            &case.body,
            std::slice::from_ref(&case.secret),
            300,
            case.timestamp_seconds + 301
        ));
    }
    assert_eq!(signs, 5);
    assert!(!file.signing_secret.is_empty());
    assert!(!file.rotation_secret.is_empty());
}

#[test]
fn rotation_headers_carry_every_secret() {
    let file: File = serde_json::from_str(WEBHOOKS).expect("webhook vectors");
    let case = file
        .cases
        .iter()
        .find(|case| case.kind == "headers")
        .expect("rotation case");
    let headers = build_standard_webhook_headers(
        &case.webhook_id,
        case.timestamp_seconds,
        &case.body,
        &case.secrets,
    )
    .expect("headers");
    let map: BTreeMap<_, _> = headers.into_iter().collect();
    assert_eq!(map["webhook-id"], case.webhook_id);
    assert_eq!(map["webhook-timestamp"], case.timestamp_seconds.to_string());
    assert_eq!(map["webhook-signature"], case.headers["webhook-signature"]);
    let signatures: Vec<&str> = map["webhook-signature"].split(' ').collect();
    assert_eq!(signatures.len(), case.secrets.len());
    assert!(signatures.iter().all(|entry| entry.starts_with("v1,")));
    for (index, secret) in case.secrets.iter().enumerate() {
        let expected =
            sign_standard_webhook(&case.webhook_id, case.timestamp_seconds, &case.body, secret)
                .expect("sign");
        assert_eq!(signatures[index], expected);
    }
}
